from collections.abc import Mapping
import math


def normalize_event(row: Mapping[str, object]) -> dict[str, int | float | str]:
    fields = {"timestamp_ms", "status", "latency_ms"}
    if not isinstance(row, Mapping) or set(row) != fields:
        raise ValueError("event must contain exactly timestamp_ms, status, latency_ms")

    timestamp = row["timestamp_ms"]
    if type(timestamp) is not int or timestamp < 0:
        raise ValueError("invalid event timestamp_ms")

    status = row["status"]
    if not isinstance(status, str) or not status.strip():
        raise ValueError("invalid event status")

    raw_latency = row["latency_ms"]
    if type(raw_latency) not in (int, float):
        raise ValueError("invalid event latency_ms")
    try:
        latency = float(raw_latency)
    except (OverflowError, ValueError):
        raise ValueError("invalid event latency_ms") from None
    if not math.isfinite(latency) or latency < 0:
        raise ValueError("invalid event latency_ms")

    return {
        "timestamp_ms": timestamp,
        "status": status.strip().lower(),
        "latency_ms": latency,
    }

