import unittest

from log_events import normalize_event


class NormalizeEventTests(unittest.TestCase):
    def test_normalizes_status_and_latency(self) -> None:
        self.assertEqual(
            normalize_event({"timestamp_ms": 7, "status": " ERROR ", "latency_ms": 2}),
            {"timestamp_ms": 7, "status": "error", "latency_ms": 2.0},
        )

    def test_rejects_wrong_fields_and_invalid_values(self) -> None:
        invalid_rows = [
            ({}, "event must contain exactly timestamp_ms, status, latency_ms"),
            (
                {"timestamp_ms": True, "status": "ok", "latency_ms": 1},
                "invalid event timestamp_ms",
            ),
            (
                {"timestamp_ms": 1, "status": " ", "latency_ms": 1},
                "invalid event status",
            ),
            (
                {"timestamp_ms": 1, "status": "ok", "latency_ms": True},
                "invalid event latency_ms",
            ),
            (
                {"timestamp_ms": 1, "status": "ok", "latency_ms": float("inf")},
                "invalid event latency_ms",
            ),
            (
                {"timestamp_ms": 1, "status": "ok", "latency_ms": 10**1000},
                "invalid event latency_ms",
            ),
        ]
        for row, message in invalid_rows:
            with self.subTest(message=message):
                with self.assertRaisesRegex(ValueError, f"^{message}$"):
                    normalize_event(row)
